/* 
 * 🏥 Bootstrap Lite v5.3.0 - نسخة خفيفة كاملة
 * يدعم: Modal, Dropdown, Tab, Collapse, Alert, Tooltip
 * الحجم: ~12KB - يعمل بدون إنترنت
 */
(function() {
    'use strict';

    // ===== 🔽 Dropdown =====
    document.querySelectorAll('[data-bs-toggle="dropdown"]').forEach(btn => {
        btn.addEventListener('click', function(e) {
            e.preventDefault();
            e.stopPropagation();
            document.querySelectorAll('.dropdown-menu.show').forEach(m => {
                if(m !== this.nextElementSibling) m.classList.remove('show');
            });
            const menu = this.nextElementSibling;
            if(menu && menu.classList.contains('dropdown-menu')) {
                menu.classList.toggle('show');
            }
        });
    });
    // معالجة إرسال النماذج
document.querySelectorAll('form').forEach(form => {
    form.addEventListener('submit', async function(e) {
        e.preventDefault();
        const submitBtn = this.querySelector('button[type="submit"]');
        const originalText = submitBtn.innerHTML;
        
        try {
            // تعطيل الزر وإظهار حالة التحميل
            submitBtn.disabled = true;
            submitBtn.innerHTML = '<span class="spinner-border spinner-border-sm me-2"></span>جاري الحفظ...';
            
            // إرسال النموذج
            const formData = new FormData(this);
            const submitter = e.submitter;
            if(submitter && submitter.name && !formData.has(submitter.name)) {
                formData.append(submitter.name, submitter.value || '1');
            }
            const response = await fetch(this.action || window.location.href, {
                method: 'POST',
                body: formData
            });
            
            if(response.ok) {
                // إغلاق المودال
                const modal = this.closest('.modal');
                if(modal) {
                    modal.classList.remove('show');
                    modal.style.display = 'none';
                    document.body.style.overflow = '';
                }
                // تحديث الصفحة
                window.location.reload();
            } else {
                throw new Error('فشل في حفظ البيانات');
            }
        } catch(error) {
            console.error('Error:', error);
            alert('حدث خطأ في حفظ البيانات');
            submitBtn.disabled = false;
            submitBtn.innerHTML = originalText;
        }
    });
});

    document.addEventListener('click', e => {
        if(!e.target.closest('[data-bs-toggle="dropdown"]')) {
            document.querySelectorAll('.dropdown-menu.show').forEach(m => m.classList.remove('show'));
        }
    });

    // ===== 🪟 Modal =====
    class Modal {
        constructor(el) { this.el = el; }
        show() {
            this.el.classList.add('show');
            this.el.style.display = 'block';
            document.body.style.overflow = 'hidden';
            this.el.focus();
            // إغلاق عند الضغط على ESC
            document.addEventListener('keydown', this.escHandler = (e) => {
                if(e.key === 'Escape') this.hide();
            });
            // إغلاق عند النقر خارج المحتوى
            this.el.addEventListener('click', this.backdropHandler = (e) => {
                if(e.target === this.el) this.hide();
            });
        }
        hide() {
            this.el.classList.remove('show');
            this.el.style.display = 'none';
            document.body.style.overflow = '';
            document.removeEventListener('keydown', this.escHandler);
            this.el.removeEventListener('click', this.backdropHandler);
        }
    }

    // تهيئة جميع المودال
    document.querySelectorAll('[data-bs-toggle="modal"]').forEach(btn => {
        btn.addEventListener('click', function(e) {
            e.preventDefault();
            const target = this.getAttribute('data-bs-target') || this.getAttribute('href');
            const modalEl = document.querySelector(target);
            if(modalEl) {
                const modal = new Modal(modalEl);
                modal.show();
                // حفظ المرجع للعناصر داخل المودال
                modalEl._modal = modal;
                // إغلاق عند زر X
                modalEl.querySelector('[data-bs-dismiss="modal"], .btn-close')?.addEventListener('click', () => modal.hide());
            }
        });
    });

    // ===== 📑 Tabs =====
    document.querySelectorAll('[data-bs-toggle="tab"]').forEach(btn => {
        btn.addEventListener('click', function(e) {
            e.preventDefault();
            const target = this.getAttribute('data-bs-target');
            // إزالة active من الكل
            this.closest('.nav')?.querySelectorAll('.nav-link').forEach(b => b.classList.remove('active'));
            document.querySelectorAll('.tab-pane').forEach(p => p.classList.remove('show', 'active'));
            // تفعيل المحدد
            this.classList.add('active');
            document.querySelector(target)?.classList.add('show', 'active');
        });
    });

    // ===== 🔽 Collapse =====
    document.querySelectorAll('[data-bs-toggle="collapse"]').forEach(btn => {
        btn.addEventListener('click', function(e) {
            e.preventDefault();
            const target = this.getAttribute('data-bs-target') || this.getAttribute('href');
            const el = document.querySelector(target);
            if(el) {
                const isShown = el.classList.contains('show');
                document.querySelectorAll('[data-bs-toggle="collapse"]').forEach(b => {
                    if(b !== btn) {
                        const t = b.getAttribute('data-bs-target') || b.getAttribute('href');
                        document.querySelector(t)?.classList.remove('show');
                    }
                });
                el.classList.toggle('show');
                el.style.maxHeight = el.classList.contains('show') ? '1000px' : '0';
                btn.setAttribute('aria-expanded', !isShown);
            }
        });
    });

    // ===== ⚠️ Alert Dismiss =====
    document.querySelectorAll('.alert-dismissible .btn-close').forEach(btn => {
        btn.addEventListener('click', function() {
            const alert = this.closest('.alert');
            if(alert) {
                alert.style.opacity = '0';
                alert.style.transform = 'translateY(-10px)';
                setTimeout(() => alert.remove(), 300);
            }
        });
    });

    // ===== 🎯 Tooltip (بسيط) =====
    document.querySelectorAll('[data-bs-toggle="tooltip"]').forEach(el => {
        el.addEventListener('mouseenter', function() {
            const title = this.getAttribute('title') || this.getAttribute('data-bs-title');
            if(title) {
                const tooltip = document.createElement('div');
                tooltip.className = 'tooltip-bs';
                tooltip.textContent = title;
                tooltip.style.cssText = 'position:absolute;background:#1e293b;color:#fff;padding:6px 12px;border-radius:6px;font-size:12px;z-index:1100;white-space:nowrap;pointer-events:none;animation:fadeIn 0.2s';
                document.body.appendChild(tooltip);
                const rect = this.getBoundingClientRect();
                tooltip.style.top = (rect.top - 35) + 'px';
                tooltip.style.right = (rect.right - 20) + 'px';
                this._tooltip = tooltip;
            }
        });
        el.addEventListener('mouseleave', function() {
            if(this._tooltip) {
                this._tooltip.style.opacity = '0';
                setTimeout(() => this._tooltip?.remove(), 200);
                delete this._tooltip;
            }
        });
    });

    // ===== 🔄 تهيئة عند تحميل الصفحة =====
    document.addEventListener('DOMContentLoaded', function() {
        // إخفاء المودال افتراضياً
        document.querySelectorAll('.modal').forEach(m => {
            if(!m.classList.contains('show')) {
                m.style.display = 'none';
            }
        });
        // تفعيل التبويب النشط
        const activeTab = document.querySelector('[data-bs-toggle="tab"].active');
        if(activeTab?.getAttribute('data-bs-target')) {
            document.querySelector(activeTab.getAttribute('data-bs-target'))?.classList.add('show', 'active');
        }
    });

    // ===== 🎨 أنماط إضافية للـ Tooltip =====
    const style = document.createElement('style');
    style.textContent = `
        @keyframes fadeIn { from { opacity: 0; transform: translateY(5px); } to { opacity: 1; transform: translateY(0); } }
        .modal { position: fixed; top: 0; right: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.5); display: flex; align-items: center; justify-content: center; z-index: 1050; }
        .modal .modal-dialog { background: #fff; border-radius: 16px; max-width: 500px; width: 90%; max-height: 90vh; overflow-y: auto; animation: slideUp 0.3s; }
        @keyframes slideUp { from { transform: translateY(30px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }
        .modal.show .modal-dialog { animation: slideUp 0.3s; }
    `;
    document.head.appendChild(style);

})();
